37	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
38	
39	type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
40	type Customer = { yearsWithMHPCO: number };
41	type Damage = { itemType: string; amount: number };
42	type QuoteStep = { op: "quote"; items: Item[] };
43	type ClaimStep = {
44	  op: "claim";
45	  policy: number;
46	  incident: { cause: string; damages: Damage[] };
47	};
48	type Step = QuoteStep | ClaimStep;
49	type Scenario = { customer: Customer; steps: Step[] };
50	
51	type QuoteResult = { premium: number };
52	type ClaimResult = { payout: number; remainingCap: number };
53	type StepResult = QuoteResult | ClaimResult;
54	
55	type PolicyState = { items: Item[]; insuranceSum: number; remainingCap: number };
56	
57	const countsByType = (items: Item[]): Map<string, number> =>
58	  items.reduce(
59	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
60	    new Map<string, number>(),
61	  );
62	
63	const groupBase = (type: string, count: number): number =>
64	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
65	    ? BLOCK_PREMIUM
66	    : count * BASE_PREMIUM[type];
67	
68	const itemsBase = (items: Item[]): number =>
69	  [...countsByType(items)].reduce(
70	    (total, [type, count]) => total + groupBase(type, count),
71	    0,
72	  );
73	
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	const isHighlyEnchanted = (item: Item): boolean =>
76	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
77	
78	const itemSurcharge = (item: Item): number => {
79	  const base = BASE_PREMIUM[item.type];
80	  const curseSurcharge = isCursed(item) ? base * CURSE_SURCHARGE_RATE : 0;
81	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
82	    ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
83	    : 0;
84	  return curseSurcharge + highEnchantmentSurcharge;
85	};
86	
87	const itemSurchargesTotal = (items: Item[]): number =>
88	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
89	
90	const roundUpInFavorOfInsurer = (amount: number): number =>
91	  Math.ceil(Math.round(amount * 1e6) / 1e6);
92	
93	const roundDownInFavorOfInsurer = (amount: number): number =>
94	  Math.floor(Math.round(amount * 1e6) / 1e6);
95	
96	const isLoyal = (customer: Customer): boolean =>
97	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
98	
99	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
100	  isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
101	
102	const firstInsuranceSurcharge = (policyBase: number): number =>
103	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
104	
105	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
106	  isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
107	
108	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
109	  const policyBase = itemsBase(items);
110	  return roundUpInFavorOfInsurer(
111	    policyBase +
112	      itemSurchargesTotal(items) +
113	      firstInsuranceSurcharge(policyBase) -
114	      loyaltyDiscount(customer, policyBase) -
115	      followUpDiscount(policyBase, isFollowUp) +
116	      PROCESSING_FEE,
117	  );
118	};
119	
120	const insuranceSum = (items: Item[]): number =>
121	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
122	
123	const createPolicy = (items: Item[]): PolicyState => {
124	  const sum = insuranceSum(items);
125	  return { items, insuranceSum: sum, remainingCap: sum * CAP_MULTIPLIER };
126	};
127	
128	const reimbursementRate = (item: Item): number =>
129	  (item.enchantment ?? 0) >= REIMBURSEMENT_HIGH_ENCHANTMENT_THRESHOLD
130	    ? REIMBURSEMENT_HIGH_ENCHANTMENT_RATE
131	    : 1;
132	
133	const damagePayout = (damage: Damage, damagedItem: Item): number =>
134	  damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE;
135	
136	const findDamagedItem = (policy: PolicyState, itemType: string): Item =>
137	  policy.items.find((i) => i.type === itemType)!;
138	
139	const payoutForDamage = (policy: PolicyState, damage: Damage): number =>
140	  damagePayout(damage, findDamagedItem(policy, damage.itemType));
141	
142	const processClaim = (policy: PolicyState, damages: Damage[]): ClaimResult => {
143	  for (const d of damages) {
144	    if (d.amount < 0) throw new Error(`negative damage amount: ${d.amount}`);
145	  }
146	  const desired = damages.reduce((sum, d) => sum + payoutForDamage(policy, d), 0);
147	  const payout = roundDownInFavorOfInsurer(Math.min(desired, policy.remainingCap));
148	  policy.remainingCap -= payout;
149	  return { payout, remainingCap: policy.remainingCap };
150	};
151	
152	export const runScenario = (scenario: unknown): unknown => {
153	  const s = scenario as Scenario;
154	  const policies = new Map<number, PolicyState>();
155	  let quoteCount = 0;
156	  const results: StepResult[] = s.steps.map((step, index) => {
157	    if (step.op === "quote") {
158	      const isFollowUp = quoteCount > 0;
159	      quoteCount += 1;
160	      policies.set(index, createPolicy(step.items));
161	      return { premium: quotePremium(step.items, s.customer, isFollowUp) };
162	    }
163	    const policy = policies.get(step.policy)!;
164	    return processClaim(policy, step.incident.damages);
165	  });
166	  return { results };
167	};
